#!/usr/bin/env python3
"""Build the dependency-free static site. Run: python3 scripts/build_site.py.
All copy, metadata and product destinations are reviewable here. No API keys.
"""
from pathlib import Path
import argparse, json, html, re
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'dist'
config=json.loads((ROOT/'site.config.json').read_text())
parser=argparse.ArgumentParser();parser.add_argument('--base-url');args=parser.parse_args()
BASE=(args.base_url or config['base_url']).rstrip('/')
if not BASE.startswith('https://'):raise SystemExit('Use an absolute HTTPS base URL')
E=lambda s:html.escape(str(s),quote=True)
def url(slug):
 path='' if slug=='index' else slug+('.html' if not BASE.endswith('.chatgpt.site') else '')
 return BASE+'/'+path
META={
'index':('Oura Ring 4 Singapore | Sleep & Recovery Smart Ring','Explore Oura Ring 4 for sleep, recovery and daily activity. Compare features, sizing and ownership costs, then get your free buying guide.'),
'ring':('Oura Ring 4 Features | Smart Ring vs Smartwatch','See how Oura Ring 4 fits everyday life. Compare a smart ring with a smartwatch, explore its design and decide which wearable suits you.'),
'sleep':('Oura Ring 4 Sleep Tracker | Sleep Insights Singapore','Understand Oura Ring 4 sleep tracking, estimated sleep stages and nightly patterns. Explore the evidence and get a guide matched to your goals.'),
'readiness':('Oura Ring 4 Readiness | Recovery & HRV Tracking','Learn how Oura Ring 4 uses sleep, heart rate and HRV trends for readiness insights. See what the score means for everyday recovery.'),
'activity':('Oura Ring 4 Fitness Tracking | Daily Activity Insights','Explore Oura Ring 4 activity tracking and daily goals. Learn how it complements a smartwatch and get a personalised fitness buying guide.'),
 'technology':('Oura Ring 4 Accuracy | Sensors & Smart Sensing','Explore Oura Ring 4 sensors, Smart Sensing and accuracy research. Understand what the evidence supports before choosing a smart ring.'),
'find-your-ring':('Oura Ring 4 Sizes & Colours | Singapore Sizing Guide','Compare Oura Ring 4 finishes and learn how to use the correct sizing kit. Save your preferences for a personalised Singapore buying guide.'),
'buy':('Oura Ring 4 Price Singapore | Membership & Buying','Understand Oura Ring 4 price, membership and sizing costs in Singapore. Compare ownership costs and find the matching OURA SG Shopee listing.'),
'contact':('Free Oura Ring Buying Guide | Features, Fit & Costs','Get a personalised Oura buying guide for sleep, recovery or activity, with sizing advice, membership details and a matching product link.'),
'privacy':('Privacy Policy | Oura Singapore Buying Guide','Read how buying-guide form information and consent choices are handled, how long details are kept and how to contact the project team.'),
'sitemap':('Oura Ring 4 Sitemap | Features, Sizing & Buying Guide','Find Oura Ring 4 feature guides, sleep and recovery information, sizing advice, price guidance and the personalised buying-guide form.'),
'team':('CS2024 Project Team | Oura Ring Singapore','Meet the CS2024 team behind this Oura Ring Singapore website, with project roles, research responsibilities and contact information.'),
'research':('Oura Ring 4 Research | Accuracy Evidence & Sources','Review Oura Ring 4 research, manufacturer documentation and accuracy evidence. See source dates, study limitations and product guidance.')}
for slug,(title,description) in META.items():
 assert len(title)<60,(slug,'title',len(title));assert len(description)<155,(slug,'description',len(description))
NAV=[('index','Overview'),('sleep','Sleep'),('readiness','Recovery'),('activity','Activity'),('ring','Ring vs watch'),('technology','Technology'),('find-your-ring','Sizing & colours'),('buy','Price & buying'),('contact','Free buying guide')]
SPECS='https://support.ouraring.com/hc/en-us/articles/33045011508115-Oura-Ring-4'
MEMBER='https://support.ouraring.com/hc/en-us/articles/4409086524819-Oura-Membership'
STUDY='https://ouraring.com/blog/smart-sensing/'
SIZING='https://support.ouraring.com/hc/en-us/articles/360025590653-How-to-Choose-the-Right-Oura-Ring-Size'
COLORS=[('Silver','#b5b8b4','45254347914'),('Black','#424440','44127154251'),('Brushed Silver','#969e98','50952933163'),('Stealth','#30342f','56502936901'),('Gold','#c8a36b','41727164270'),('Rose Gold','#b78673','48102953377')]
def shop4(name,item):return f'https://shopee.sg/Oura-Ring-4-{name.replace(" ","-")}-%28Size-4-15%29-Smart-Ring-for-Health-Sleep-Fitness-and-More-i.1697647881.{item}'
RINGS=[{'generation':4,'finish':n,'color':c,'itemId':i,'url':shop4(n,i),'price':None,'availability':'Check size availability on Shopee'} for n,c,i in COLORS]
OTHER=[
('Ring 5 Silver','https://shopee.sg/Oura-Ring-5-Silver-%28Size-6-13%29-Smart-Ring-for-Health-Sleep-Fitness-and-More-Size-First-with-Oura-Ring-5-Sizing-Kit-i.1697647881.44231157679'),
('Ring 5 Black','https://shopee.sg/Oura-Ring-5-Black-%28Size-6-13%29-Smart-Ring-for-Health-Sleep-Fitness-and-More-Size-First-with-Oura-Ring-5-Sizing-Kit-i.1697647881.57261091249'),
('Ring 5 Brushed Silver','https://shopee.sg/Oura-Ring-5-Brushed-Silver-%28Size-6-13%29-Smart-Ring-for-Health-Sleep-Fitness-and-More-Size-First-with-Sizing-Kit-i.1697647881.53511078029'),
('Ring 5 Stealth','https://shopee.sg/Oura-Ring-5-Stealth-%28Size-6-13%29-Smart-Ring-for-Health-Sleep-Fitness-and-More-Size-First-with-Oura-Ring-5-Sizing-Kit-i.1697647881.54661078964'),
('Ring 5 Gold','https://shopee.sg/Oura-Ring-5-Gold-%28Size-6-13%29-Smart-Ring-for-Health-Sleep-Fitness-and-More-Size-First-with-Oura-Ring-5-Sizing-Kit-i.1697647881.42831157598'),
('Ring 5 Deep Rose','https://shopee.sg/Oura-Ring-5-Deep-Rose-%28Size-6-13%29-Smart-Ring-for-Health-Sleep-Fitness-More-Size-First-with-Oura-Ring-5-Sizing-Kit-i.1697647881.40631154169'),
('Ring 5 Sizing Kit','https://shopee.sg/Oura-Ring-5-Sizing-Kit-Size-Before-You-Buy-Unique-Sizing-Not-Standard-Ring-Sizes-Non-Returnable-Non-Refundable-i.1697647881.57411090076')]
KIT4='https://shopee.sg/Oura-Ring-4-Sizing-Kit-Non-Returnable-Non-Refundable-i.1697647881.45352958203'
(OUT/'assets/catalog.js').write_text('/* Listing identity, not a stock or price guarantee. No personal data. */\nwindow.OuraCatalog = '+json.dumps({'rings':RINGS,'otherProducts':[{'name':n,'url':u} for n,u in OTHER],'kit4':KIT4,'offer':config['offer'],'reviewed':config['reviewed']},ensure_ascii=False,indent=2)+';\n')
(root_catalog:=ROOT/'docs/product-links.json').write_text(json.dumps({'ring4':RINGS,'other':OTHER,'historicalRing4SizingKit':KIT4,'note':'Recovered links reviewed 5 November 2026. Five indexed Ring 4 finish pages showed sold out on 10 November 2026. Black could not be fetched. Live purchasable stock remains unconfirmed. Confirm stock and terms on Shopee.'},indent=2))
def guide(label='Get my free buying guide',focus='',cls=''):
 href='contact.html'+('?interest='+focus if focus else '')
 return f'<a class="button guide-link {cls}" href="{href}" data-guide-interest="{focus}">{E(label)}<span aria-hidden="true">↗</span></a>'
def shop(label='Shop Ring 4 on Shopee',cls=''):
 return f'<a class="button shop-link {cls}" data-shop-link href="{E(RINGS[0]["url"])}" rel="noopener noreferrer">{E(label)}<span aria-hidden="true">↗</span></a>'
def a(label,href,cls='text-link'):return f'<a class="{cls}" href="{E(href)}">{label}<span aria-hidden="true"> ↗</span></a>'
def ring():return '<div class="ring-stage"><canvas class="ring-canvas" aria-label="Original Oura Ring 4 titanium band illustration"></canvas><div class="ring-fallback" aria-hidden="true"></div><span class="stage-label">TITANIUM / ORIGINAL FORM STUDY</span></div>'
def mast(kicker,h1,copy):return f'<section class="page-mast section grid-bg"><span class="eyebrow">{kicker}</span><h1>{h1}</h1><p class="large-copy">{copy}</p></section>'
def rows(items):return '<div class="editorial-rows">'+''.join(f'<article><span>0{i+1}</span><h3>{h}</h3><p>{b}</p></article>' for i,(h,b) in enumerate(items))+'</div>'
def proof():return f'<div class="proof-strip"><span>SOURCED PRODUCT FACTS</span><p>Understand the evidence, choose the right sizing kit and see membership clearly before you buy.</p>{a("Explore our evidence", "research.html")}</div>'
def faqs(items):return '<section class="section cream faq-section"><span class="eyebrow">YOUR QUESTIONS, ANSWERED</span><h2>Before you choose.</h2>'+''.join(f'<details><summary>{E(q)}</summary><p>{ans}</p></details>' for q,ans in items)+'</section>'
def offer_terms():return '<details class="offer-terms"><summary>Proposed campaign details</summary><dl>'+''.join(f'<div><dt>{E(k.replace("_"," ").title())}</dt><dd>{E(v)}</dd></div>' for k,v in config['offer'].items())+'</dl><p class="fine">Campaign concept for the project. No live voucher, free-kit entitlement or delivery promise is offered.</p></details>'

def action(title='Ready to choose your ring?',copy='Choose your finish and size on Shopee, or get a personalised guide if you would like help with fit and features.',focus=''):
 return f'<section class="section action-section"><span class="eyebrow">YOUR NEXT STEP</span><h2>{title}</h2><p class="large-copy">{copy}</p><div class="purchase-actions">{shop()}<a class="text-link guide-link secondary-guide" href="contact.html" data-guide-interest="{focus}">Help me choose: free buying guide ↗</a></div></section>'

def render(slug,body,faq=None,noindex=False):
 title,desc=META[slug];name=dict(NAV).get(slug,{'privacy':'Privacy Policy','sitemap':'Sitemap','team':'Team','research':'Research & sources'}.get(slug,slug));image=BASE+'/assets/ring-poster.svg'
 schemas=[{'@context':'https://schema.org','@type':'WebPage','name':title,'description':desc,'url':url(slug)}, {'@context':'https://schema.org','@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Overview','item':url('index')}]+([] if slug=='index' else [{'@type':'ListItem','position':2,'name':name,'item':url(slug)}])}]
 if slug in ['index','ring']:schemas.append({'@context':'https://schema.org','@type':'Product','name':'Oura Ring 4','model':'Oura Ring 4','brand':{'@type':'Brand','name':'Oura'},'description':'Titanium smart ring for sleep, readiness and everyday activity insights.','image':image,'url':url('ring')})
 if faq:
  clean=lambda v:html.unescape(re.sub('<[^>]+>','',v))
  schemas.append({'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':clean(ans)}} for q,ans in faq]})
 nav=''.join(f'<a href="{s}.html" '+('aria-current="page"' if s==slug else '')+f'>{i+1:02} / {n}</a>' for i,(s,n) in enumerate(NAV))
 cinema='<link rel="stylesheet" href="assets/cinema.css?v=8">' if slug=='index' else ''
 scripts='<script src="assets/catalog.js?v=8" defer></script><script src="assets/app.js?v=8" defer></script>'+('<script src="assets/cinema.js?v=8" defer></script>' if slug=='index' else '')+'<script src="assets/conversion.js?v=8" defer></script>'
 footer=f'''<footer><div class="footer-grid"><div class="wordmark">oura<span>RING 4 / FORM & FUNCTION</span></div><div>{''.join(f'<a href="{s}.html">{n}</a>' for s,n in NAV)}</div><div><a href="privacy.html">Privacy Policy</a><a href="research.html">Research & sources</a><a href="team.html">Project team</a></div></div><p class="fine student-notice">Independent CS2024 student concept. Not affiliated with Oura or OURA SG. Campaign ideas are proposals; purchases take place on Shopee.</p><div class="footer-end"><span>SINGAPORE / FORM & FUNCTION</span><a href="#main">BACK TO TOP ↑</a></div></footer>'''
 sticky='' if slug in ['contact','privacy','team','sitemap'] else '<div class="mobile-guide">'+shop()+'</div>'
 out=f'''<!doctype html><html lang="en-SG"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{E(desc)}"><meta name="theme-color" content="#30372e"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow'}"><link rel="canonical" href="{E(url(slug))}"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{E(url(slug))}"><meta property="og:image" content="{E(image)}"><title>{E(title)}</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css?v=8">{cinema}<link rel="stylesheet" href="assets/conversion.css?v=8"><link rel="stylesheet" href="assets/mobile.css?v=8"><link rel="stylesheet" href="assets/readability.css?v=8">{scripts}<script type="application/ld+json">{json.dumps(schemas).replace('</','<\\/')}</script></head><body data-page="{slug}"><a class="skip" href="#main">Skip to content</a><header><a class="wordmark" href="index.html" aria-label="Oura Ring 4 overview">oura<span>RING 4</span></a><div class="header-right"><a class="small-buy shop-link" data-shop-link href="{E(RINGS[0]['url'])}" rel="noopener noreferrer">Shop Ring 4 ↗</a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="menu">● &nbsp; MENU</button></div></header><nav id="menu" hidden aria-label="Main navigation">{nav}<a href="research.html">Research & sources</a><a href="team.html">Project team</a><a href="privacy.html">Privacy Policy</a></nav><main id="main">{body}{faqs(faq) if faq else ''}</main>{footer}{sticky}</body></html>'''
 out=out.translate(str.maketrans('', '', '↗↘↙↖↑↓←→↺●\ufe0f'))
 (OUT/(slug+'.html')).write_text(out)

# Keep the approved continuous cinema and physics. Change messaging and next steps only.
home=(ROOT/'src/home-cinema.html').read_text()
home=home.replace('<div class="cinema-tagline">MADE FOR YOUR FINGER. TUNED TO YOUR LIFE.</div>','<div class="cinema-tagline">SMART RING FOR SLEEP & RECOVERY / SINGAPORE</div>')
home=home.replace('aria-label="Oura Ring 4"','aria-label="Oura Ring 4 smart ring for sleep and recovery in Singapore"')
