(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n')
(OUT/'.nojekyll').touch()
print(f'Built {len(META)} primary pages. Canonical base: {BASE}')
